1	/****************************************************************************
2	 * app/velaguard/vg_ptt.c
3	 *
4	 * USER1 按住说话事件状态机，纯逻辑，无 NuttX 依赖。
5	 * 接口与时序说明见 vg_ptt.h。
6	 ****************************************************************************/
7	
8	#include "vg_ptt.h"
9	
10	#include <stddef.h>
11	
12	/**
13	  * @brief  两个单调毫秒时刻的差值，按无符号相减以容忍回绕。
14	  * @param  now   较晚时刻。
15	  * @param  then  较早时刻。
16	  * @retval 毫秒差。
17	  */
18	static uint32_t since(uint32_t now, uint32_t then)
19	{
20	  return now - then;
21	}
22	
23	/**
24	  * @brief  距离 due 还有多久，已过期返回 0。
25	  * @note   用有符号差判断先后；单次间隔须小于 2^31 毫秒。
26	  * @param  due_ms  到期时刻。
27	  * @param  now_ms  当前时刻。
28	  * @retval 0 或剩余毫秒。
29	  */
30	static uint32_t wait_until(uint32_t due_ms, uint32_t now_ms)
31	{
32	  int32_t delta = (int32_t)(due_ms - now_ms);
33	
34	  return (delta <= 0) ? 0u : (uint32_t)delta;
35	}
36	
37	void vg_ptt_init(struct vg_ptt *ptt, bool level, uint32_t now_ms)
38	{
39	  if (ptt == NULL)
40	    {
41	      return;
42	    }
43	
44	  /* 上电即按住不当成一次录音：把当前电平直接当作已确认值，并且要求先
45	   * 见到一次确认的松手才解锁按下。否则按下边沿早已过去，却会在第一次
46	   * 更新时被当成新会话。 */
47	
48	  ptt->state = VG_PTT_IDLE;
49	  ptt->raw_level = level;
50	  ptt->stable_level = level;
51	  ptt->started = true;
52	  ptt->ungated = !level;
53	  ptt->edge_ms = now_ms;
54	  ptt->press_ms = 0;
55	}
56	
57	enum vg_ptt_event vg_ptt_update(struct vg_ptt *ptt, bool level,
58	                                uint32_t now_ms,
59	                                struct vg_ptt_event_record *rec)
60	{
61	  struct vg_ptt_event_record scratch;
62	  enum vg_ptt_event event = VG_PTT_EV_NONE;
63	  bool submit = false;
64	
65	  if (rec == NULL)
66	    {
67	      rec = &scratch;
68	    }
69	
70	  rec->type = VG_PTT_EV_NONE;
71	  rec->reason = VG_PTT_SUBMIT_RELEASE;
72	  rec->press_ms = 0;
73	  rec->duration_ms = 0;
74	
75	  if (ptt == NULL)
76	    {
77	      return VG_PTT_EV_NONE;
78	    }
79	
80	  if (!ptt->started)
81	    {
82	      vg_ptt_init(ptt, level, now_ms);
83	      return VG_PTT_EV_NONE;
84	    }
85	
86	  /* 记录未确认的电平跳变。边沿时刻在这里存档，确认后按边沿而不是按确认
87	   * 时刻计时，这样时长与用户实际按住的时间一致。 */
88	
89	  if (level != ptt->raw_level)
90	    {
91	      ptt->raw_level = level;
92	      ptt->edge_ms = now_ms;
93	    }
94	
95	  /* 电平保持稳定达到去抖窗口才确认；短于窗口的跳变被吞掉。 */
96	
97	  if (ptt->raw_level != ptt->stable_level &&
98	      since(now_ms, ptt->edge_ms) >= VG_PTT_DEBOUNCE_MS)
99	    {
100	      ptt->stable_level = ptt->raw_level;
101	    }
102	
103	  switch (ptt->state)
104	    {
105	      case VG_PTT_IDLE:
106	        if (!ptt->stable_level)
107	          {
108	            /* 已确认的松手：此后的按下边沿才是新会话的起点。 */
109	
110	            ptt->ungated = true;
111	          }
112	        else if (ptt->ungated)
113	          {
114	            ptt->state = VG_PTT_RECORDING;
115	            ptt->press_ms = ptt->edge_ms;
116	            event = VG_PTT_EV_BEGIN;
117	          }
118	
119	        break;
120	
121	      case VG_PTT_RECORDING:
122	
123	        /* 先判用户松手，再判上限：松手边沿正好落在 15 秒整点时按松手
124	         * 提交，不会同一轮再补一次超时提交。
125	         *
126	         * 电平尚未确认时按 raw 判断：用户在去抖窗口内已经松手，说明这一
127	         * 次不是长按，不能因为等待确认就超出上限自动提交。 */
128	
129	        if (!ptt->raw_level)
130	          {
131	            if (!ptt->stable_level)
132	              {
133	                ptt->state = VG_PTT_IDLE;
134	                ptt->ungated = true;
135	                submit = true;
136	              }
137	          }
138	        else if (since(now_ms, ptt->press_ms) >= VG_PTT_MAX_HOLD_MS)
139	          {
140	            ptt->state = VG_PTT_HELD;
141	            submit = true;
142	          }
143	
144	        break;
145	
146	      case VG_PTT_HELD:
147	
148	        /* 已按上限提交，只等松手，期间不再产生事件。 */
149	
150	        if (!ptt->stable_level)
151	          {
152	            ptt->state = VG_PTT_IDLE;
153	            ptt->ungated = true;
154	          }
155	
156	        break;
157	    }
158	
159	  if (submit)
160	    {
161	      event = VG_PTT_EV_SUBMIT;
162	      rec->press_ms = ptt->press_ms;
163	
164	      if (ptt->state == VG_PTT_HELD)
165	        {
166	          rec->reason = VG_PTT_SUBMIT_TIMEOUT;
167	          rec->duration_ms = VG_PTT_MAX_HOLD_MS;
168	        }
169	      else
170	        {
171	          rec->reason = VG_PTT_SUBMIT_RELEASE;
172	          rec->duration_ms = since(ptt->edge_ms, ptt->press_ms);
173	        }
174	    }
175	  else if (event == VG_PTT_EV_BEGIN)
176	    {
177	      rec->press_ms = ptt->press_ms;
178	    }
179	
180	  rec->type = event;
181	  return event;
182	}
183	
184	int vg_ptt_next_timeout_ms(const struct vg_ptt *ptt, uint32_t now_ms)
185	{
186	  uint32_t best = 0;
187	  bool have = false;
188	
189	  if (ptt == NULL || !ptt->started)
190	    {
191	      return -1;
192	    }
193	
194	  /* 电平跳变待确认：去抖窗口到期时回来确认 */
195	
196	  if (ptt->raw_level != ptt->stable_level)
197	    {
198	      best = wait_until(ptt->edge_ms + VG_PTT_DEBOUNCE_MS, now_ms);
199	      have = true;
200	    }
201	
202	  /* 录音中：上限到期时回来提交 */
203	
204	  if (ptt->state == VG_PTT_RECORDING)
205	    {
206	      uint32_t cap = wait_until(ptt->press_ms + VG_PTT_MAX_HOLD_MS, now_ms);
207	
208	      if (!have || cap < best)
209	        {
210	          best = cap;
211	        }
212	
213	      have = true;
214	    }
215	
216	  return have ? (int)best : -1;
217	}
218	
219	const char *vg_ptt_state_name(enum vg_ptt_state state)
220	{
221	  switch (state)
222	    {
223	      case VG_PTT_IDLE:
224	        return "idle";
225	
226	      case VG_PTT_RECORDING:
227	        return "recording";
228	
229	      case VG_PTT_HELD:
230	        return "held";
231	
232	      default:
233	        return "?";
234	    }
235	}
236	
237	const char *vg_ptt_reason_name(enum vg_ptt_submit_reason reason)
238	{
239	  switch (reason)
240	    {
241	      case VG_PTT_SUBMIT_RELEASE:
242	        return "release";
243	
244	      case VG_PTT_SUBMIT_TIMEOUT:
245	        return "timeout";
246	
247	      default:
248	        return "?";
249	    }
250	}
