1	/****************************************************************************
2	 * app/velaguard/vg_ptt_board.c
3	 *
4	 * USER1 按住说话板端适配层。
5	 *
6	 * 线程模型：
7	 *   ptt 线程 open("/dev/buttons")，用 poll() 等待按键事件；每次醒来读一次
8	 *   电平并喂给 vg_ptt。没有按键时 poll 按 VG_PTT_STOP_POLL_MS 到期返回，
9	 *   因此停止请求有界；有按键时由驱动唤醒。去抖确认与 15 秒上限都靠
10	 *   vg_ptt_next_timeout_ms() 给出的到期时刻醒来，不做固定周期轮询。
11	 *
12	 * 事件回调在本线程执行，不得阻塞，也不得调用 vg_ptt_* 的写接口。
13	 ****************************************************************************/
14	
15	#include <nuttx/config.h>
16	
17	#ifdef CONFIG_VG_PTT
18	
19	#include "vg_ptt_board.h"
20	
21	#include <errno.h>
22	#include <fcntl.h>
23	#include <poll.h>
24	#include <pthread.h>
25	#include <stdbool.h>
26	#include <stdio.h>
27	#include <string.h>
28	#include <time.h>
29	#include <unistd.h>
30	
31	/* BUTTON_USER and the bit position behind it come from the board header, not
32	 * from <nuttx/input/buttons.h>; the two must be read together. */
33	
34	#include <arch/board/board.h>
35	#include <nuttx/board.h>
36	#include <nuttx/input/buttons.h>
37	#include <nuttx/sched.h>
38	
39	#ifndef CONFIG_VG_PTT_DEVPATH
40	#  define CONFIG_VG_PTT_DEVPATH "/dev/buttons"
41	#endif
42	
43	#ifndef CONFIG_VG_PTT_STACKSIZE
44	#  define CONFIG_VG_PTT_STACKSIZE 4096
45	#endif
46	
47	#ifndef CONFIG_VG_PTT_PRIORITY
48	#  define CONFIG_VG_PTT_PRIORITY 90
49	#endif
50	
51	#define VG_PTT_STOP_DEFAULT_MS 2000
52	
53	/* 空闲等待的安全窗口。按键边沿由 EXTI 唤醒 poll，板端已实测可唤醒：一次
54	 * 110 ms 的按下被完整记录成 begin/submit，而 1 Hz 采样不可能量出这个时长。
55	 *
56	 * 这个窗口不用于发现按键，只保证两件事有确定上界：停止请求，以及状态机
57	 * 自己给出的到期时刻（去抖确认、15 秒上限）即使被漏唤醒也能补上。1 Hz
58	 * 的 poll 超时加一次 read() 不构成对采集或界面有影响的忙轮询。
59	 */
60	
61	#define VG_PTT_SAFETY_WINDOW_MS  1000
62	
63	/* 板端可视反馈：按键事件直接驱动一颗 LED，按住亮、松开灭，便于在没有
64	 * 音频和界面之前确认按键通路。LD3（NuttX 的绿灯位，实际是 Arduino 连接器
65	 * 旁的 LD8，PD3）专用于按键，心跳用的是 LD1（PJ2），两者不会混淆。
66	 */
67	
68	#ifndef CONFIG_VG_PTT_LED
69	#  define CONFIG_VG_PTT_LED 2
70	#endif
71	
72	static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
73	
74	/* 线程 detach 后不能 join，只用这个标志表示是否曾经成功启动过 */
75	
76	static bool g_thread_valid;
77	static volatile bool g_stop;
78	static bool g_running;
79	static bool g_led_ready;
80	static char g_devpath[32] = CONFIG_VG_PTT_DEVPATH;
81	
82	static struct vg_ptt g_ptt;
83	static struct vg_ptt_stats g_stats;
84	static vg_ptt_event_fn g_callback;
85	static void *g_callback_arg;
86	
87	/**
88	  * @brief  读取单调时钟毫秒。
89	  * @retval 自开机起的毫秒数，截断到 32 位；回绕由 vg_ptt 的无符号相减处理。
90	  */
91	static uint32_t now_ms(void)
92	{
93	  struct timespec ts;
94	
95	  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
96	    {
97	      return 0;
98	    }
99	
100	  return (uint32_t)((uint64_t)ts.tv_sec * 1000ull +
101	                    (uint64_t)(ts.tv_nsec / 1000000ull));
102	}
103	
104	/**
105	  * @brief  把一次按键读取结果换算成电平。
106	  * @note   board_buttons() 的位含义来自 board.h：位为 1 表示按下。
107	  * @param  sample  驱动返回的位集合。
108	  * @retval true 表示 USER1 处于按下状态。
109	  */
110	static bool sample_pressed(btn_buttonset_t sample)
111	{
112	  return (sample & (1u << BUTTON_USER)) != 0;
113	}
114	
115	/**
116	  * @brief  点亮或熄灭按键反馈 LED。
117	  * @param  on  true 点亮。
118	  * @retval None
119	  */
120	static void led_set(bool on)
121	{
122	  if (g_led_ready)
123	    {
124	      board_userled(CONFIG_VG_PTT_LED, on);
125	    }
126	}
127	
128	/**
129	  * @brief  默认事件处理：没有音频层时做板端可视反馈与可追踪输出。
130	  * @note   录音中 LED 常亮，提交后熄灭，因此按键是否被受理可以直接看板子。
131	  *         BVO-03/05 接入录音后由上层替换，这里不保存任何音频数据。
132	  * @param  rec  事件记录。
133	  * @param  arg  未使用。
134	  * @retval None
135	  */
136	static void default_handler(const struct vg_ptt_event_record *rec, void *arg)
137	{
138	  (void)arg;
139	
140	  if (rec->type == VG_PTT_EV_BEGIN)
141	    {
142	      led_set(true);
143	      printf("vgptt: begin (press_ms=%u)\n", (unsigned)rec->press_ms);
144	    }
145	  else if (rec->type == VG_PTT_EV_SUBMIT)
146	    {
147	      led_set(false);
148	      printf("vgptt: submit %s duration_ms=%u\n",
149	             vg_ptt_reason_name(rec->reason),
150	             (unsigned)rec->duration_ms);
151	    }
152	}
153	
154	/**
155	  * @brief  记录一次事件到统计并交给上层。
156	  * @param  rec  事件记录。
157	  * @retval None
158	  */
159	static void publish(const struct vg_ptt_event_record *rec)
160	{
161	  vg_ptt_event_fn fn;
162	
163	  pthread_mutex_lock(&g_lock);
164	
165	  if (rec->type == VG_PTT_EV_BEGIN)
166	    {
167	      g_stats.begins++;
168	    }
169	  else if (rec->type == VG_PTT_EV_SUBMIT)
170	    {
171	      g_stats.submits++;
172	      g_stats.last_duration_ms = rec->duration_ms;
173	      if (rec->reason == VG_PTT_SUBMIT_TIMEOUT)
174	        {
175	          g_stats.timeouts++;
176	        }
177	    }
178	
179	  fn = g_callback;
180	  pthread_mutex_unlock(&g_lock);
181	
182	  /* 回调在锁外执行，避免上层处理阻塞统计读取 */
183	
184	  fn(rec, g_callback_arg);
185	}
186	
187	/**
188	  * @brief  读一次按键电平并推进状态机。
189	  * @param  fd  /dev/buttons。
190	  * @retval 0   成功（可能没有事件）。
191	  * @retval <0  读取失败。
192	  */
193	static int poll_once(int fd)
194	{
195	  struct vg_ptt_event_record rec;
196	  btn_buttonset_t sample = 0;
197	  uint32_t now;
198	  ssize_t n;
199	  bool raw;
200	
201	  n = read(fd, &sample, sizeof(sample));
202	  if (n != (ssize_t)sizeof(sample))
203	    {
204	      pthread_mutex_lock(&g_lock);
205	      g_stats.read_errors++;
206	      pthread_mutex_unlock(&g_lock);
207	      return -1;
208	    }
209	
210	  raw = sample_pressed(sample);
211	
212	  /* 原始电平直接跟 LED：不经过去抖与状态机，按键有没有被读到一眼可见 */
213	
214	  led_set(raw);
215	
216	  now = now_ms();
217	
218	  pthread_mutex_lock(&g_lock);
219	  g_stats.samples++;
220	  if (raw)
221	    {
222	      g_stats.raw_highs++;
223	    }
224	
225	  g_stats.last_event_ms = now;
226	  vg_ptt_update(&g_ptt, raw, now, &rec);
227	  g_stats.state = g_ptt.state;
228	  pthread_mutex_unlock(&g_lock);
229	
230	  if (rec.type != VG_PTT_EV_NONE)
231	    {
232	      publish(&rec);
233	    }
234	
235	  return 0;
236	}
237	
238	/**
239	  * @brief  ptt 线程主体。
240	  * @param  arg  未使用。
241	  * @retval NULL
242	  */
243	static int ptt_task(int argc, char *argv[])
244	{
245	  struct pollfd pfd;
246	  int fd;
247	  uint32_t now;
248	
249	  (void)argc;
250	  (void)argv;
251	
252	  fd = open(g_devpath, O_RDONLY);
253	  if (fd < 0)
254	    {
255	      printf("vgptt: open %s failed: %d\n", g_devpath, errno);
256	      pthread_mutex_lock(&g_lock);
257	      g_running = false;
258	      pthread_mutex_unlock(&g_lock);
259	      return 1;
260	    }
261	
262	  /* 以当前电平作为起点：上电即按住不会被当成一次会话 */
263	
264	  {
265	    btn_buttonset_t sample = 0;
266	
267	    if (read(fd, &sample, sizeof(sample)) == (ssize_t)sizeof(sample))
268	      {
269	        now = now_ms();
270	        pthread_mutex_lock(&g_lock);
271	        vg_ptt_init(&g_ptt, sample_pressed(sample), now);
272	        g_stats.state = g_ptt.state;
273	        g_stats.last_event_ms = now;
274	        g_stats.running = true;
275	        pthread_mutex_unlock(&g_lock);
276	      }
277	  }
278	
279	  /* 按键反馈 LED：确认板上有输出控制权再点亮，避免和心跳 LED 抢同一个 */
280	
281	  if (board_userled_initialize() > (uint32_t)CONFIG_VG_PTT_LED)
282	    {
283	      g_led_ready = true;
284	      led_set(false);
285	    }
286	
287	  pthread_mutex_lock(&g_lock);
288	  g_stats.opened = true;
289	  g_stats.running = true;
290	  g_stats.state = g_ptt.state;
291	  pthread_mutex_unlock(&g_lock);
292	
293	  printf("vgptt: watching %s (led=%d)\n", g_devpath, CONFIG_VG_PTT_LED);
294	
295	  while (!g_stop)
296	    {
297	      int timeout_ms;
298	      int ret;
299	
300	      /* 等待截止取状态机给出的最近到期时刻（去抖确认或 15 秒上限），没有
301	       * 待办事项时用安全窗口，让停止请求有确定上界。 */
302	
303	      pthread_mutex_lock(&g_lock);
304	      timeout_ms = vg_ptt_next_timeout_ms(&g_ptt, now_ms());
305	      pthread_mutex_unlock(&g_lock);
306	
307	      if (timeout_ms < 0 || (uint32_t)timeout_ms > VG_PTT_SAFETY_WINDOW_MS)
308	        {
309	          timeout_ms = (int)VG_PTT_SAFETY_WINDOW_MS;
310	        }
311	
312	      pfd.fd = fd;
313	      pfd.events = POLLIN;
314	      pfd.revents = 0;
315	
316	      ret = poll(&pfd, 1, timeout_ms);
317	      if (ret < 0)
318	        {
319	          if (errno == EINTR)
320	            {
321	              continue;
322	            }
323	
324	          pthread_mutex_lock(&g_lock);
325	          g_stats.poll_errors++;
326	          pthread_mutex_unlock(&g_lock);
327	
328	          /* poll 失败时退避，避免错误循环占满 CPU */
329	
330	          usleep(100 * 1000);
331	          continue;
332	        }
333	
334	      if (g_stop)
335	        {
336	          break;
337	        }
338	
339	      pthread_mutex_lock(&g_lock);
340	      if (ret == 0)
341	        {
342	          g_stats.wake_timeouts++;
343	        }
344	      else
345	        {
346	          g_stats.wake_events++;
347	        }
348	
349	      pthread_mutex_unlock(&g_lock);
350	
351	      /* 驱动只在状态变化时通知；到期醒来时没有按键事件也要推进状态机，
352	       * 否则 15 秒上限不会被判定。 */
353	
354	      (void)poll_once(fd);
355	    }
356	
357	  close(fd);
358	
359	  led_set(false);
360	
361	  pthread_mutex_lock(&g_lock);
362	  g_stats.opened = false;
363	  g_running = false;
364	  pthread_mutex_unlock(&g_lock);
365	
366	  printf("vgptt: stopped\n");
367	  return 0;
368	}
369	
370	int vg_ptt_start(const char *devpath, vg_ptt_event_fn fn, void *arg)
371	{
372	  int task;
373	
374	  pthread_mutex_lock(&g_lock);
375	
376	  if (g_running)
377	    {
378	      pthread_mutex_unlock(&g_lock);
379	      return 0;
380	    }
381	
382	  if (devpath != NULL && devpath[0] != '\0')
383	    {
384	      strncpy(g_devpath, devpath, sizeof(g_devpath) - 1);
385	      g_devpath[sizeof(g_devpath) - 1] = '\0';
386	    }
387	
388	  g_callback = (fn != NULL) ? fn : default_handler;
389	  g_callback_arg = arg;
390	  g_stop = false;
391	
392	  /* 统计清零；状态机在按键任务里按当前电平重新初始化 */
393	
394	  memset(&g_stats, 0, sizeof(g_stats));
395	  g_stats.state = g_ptt.state;
396	
397	  pthread_mutex_unlock(&g_lock);
398	
399	  /* 用 task_create 而不是 pthread：NSH 里的 builtin 命令跑在自己的任务组
400	   * 里，命令返回后该组连同组内 pthread 一起被回收，按键线程会随之消失。
401	   * 任务属于系统任务组，不受单条 NSH 命令的生命周期影响。 */
402	
403	  task = task_create("vgptt", CONFIG_VG_PTT_PRIORITY,
404	                     CONFIG_VG_PTT_STACKSIZE, ptt_task, NULL);
405	  if (task < 0)
406	    {
407	      printf("vgptt: task create failed: %d\n", task);
408	      return task;
409	    }
410	
411	  pthread_mutex_lock(&g_lock);
412	  g_thread_valid = true;
413	  g_running = true;
414	  pthread_mutex_unlock(&g_lock);
415	
416	  return 0;
417	}
418	
419	int vg_ptt_stop(int wait_ms)
420	{
421	  bool valid;
422	  int waited = 0;
423	
424	  if (wait_ms <= 0)
425	    {
426	      wait_ms = VG_PTT_STOP_DEFAULT_MS;
427	    }
428	
429	  pthread_mutex_lock(&g_lock);
430	  valid = g_thread_valid;
431	  g_stop = true;
432	  pthread_mutex_unlock(&g_lock);
433	
434	  if (!valid)
435	    {
436	      return 0;
437	    }
438	
439	  /* 按键任务最多在一个采样周期内看到 g_stop；默认等待 2 秒留有充足余量。 */
440	
441	  while (waited < wait_ms)
442	    {
443	      pthread_mutex_lock(&g_lock);
444	      if (!g_running)
445	        {
446	          g_thread_valid = false;
447	          pthread_mutex_unlock(&g_lock);
448	          return 0;
449	        }
450	
451	      pthread_mutex_unlock(&g_lock);
452	
453	      usleep(20 * 1000);
454	      waited += 20;
455	    }
456	
457	  printf("vgptt: stop timed out after %d ms\n", wait_ms);
458	  return -1;
459	}
460	
461	void vg_ptt_get_stats(struct vg_ptt_stats *out)
462	{
463	  if (out == NULL)
464	    {
465	      return;
466	    }
467	
468	  pthread_mutex_lock(&g_lock);
469	  *out = g_stats;
470	  pthread_mutex_unlock(&g_lock);
471	}
472	
473	void vg_ptt_reset_stats(void)
474	{
475	  bool running;
476	  bool opened;
477	
478	  pthread_mutex_lock(&g_lock);
479	
480	  running = g_stats.running;
481	  opened = g_stats.opened;
482	  memset(&g_stats, 0, sizeof(g_stats));
483	  g_stats.running = running;
484	  g_stats.opened = opened;
485	  g_stats.state = g_ptt.state;
486	
487	  pthread_mutex_unlock(&g_lock);
488	}
