490	int vg_ptt_probe_level(bool *pressed)
491	{
492	  btn_buttonset_t sample = 0;
493	  ssize_t n;
494	  int fd;
495	
496	  if (pressed == NULL)
497	    {
498	      return -EINVAL;
499	    }
500	
501	  fd = open(g_devpath, O_RDONLY);
502	  if (fd < 0)
503	    {
504	      return -errno;
505	    }
