163	
164	int main(int argc, FAR char *argv[])
165	{
166	  if (argc < 2)
167	    {
168	      vg_audio_usage();
169	      return EXIT_FAILURE;
170	    }
171	
172	  if (strcmp(argv[1], "fixtures") == 0)
173	    {
174	      const unsigned char *data[] = {vg_audio_tone, vg_audio_speech};
175	      const size_t sizes[] = {sizeof(vg_audio_tone), sizeof(vg_audio_speech)};
176	      const char *names[] = {"/mnt/emmc/bvo04/tone.wav",
177	                             "/mnt/emmc/bvo04/speech.wav"};
178	      int i;
179	      if (mkdir("/mnt/emmc/bvo04", 0755) < 0 && errno != EEXIST)
180	        {
181	          return EXIT_FAILURE;
182	        }
183	
184	      for (i = 0; i < 2; i++)
185	        {
186	          size_t off = 0;
187	          int fd = open(names[i], O_WRONLY | O_CREAT | O_TRUNC, 0644);
188	          if (fd < 0)
189	            {
190	              return EXIT_FAILURE;
191	            }
192	
193	          while (off < sizes[i])
194	            {
195	              ssize_t n = write(fd, data[i] + off, sizes[i] - off);
196	              if (n <= 0)
197	                {
198	                  close(fd);
199	                  return EXIT_FAILURE;
200	                }
201	
202	              off += n;
203	            }
204	
205	          {
206	            int sync_result = fsync(fd);
207	            int close_result = close(fd);
208	            if (sync_result < 0 || close_result < 0)
209	              {
210	                return EXIT_FAILURE;
211	              }
212	          }
213	
214	          printf("vgaudio: fixture %s bytes=%u\n", names[i], (unsigned)off);
215	        }
216	
217	      /* Five copies of the generated 1 kHz PCM, with updated WAV lengths.
218	       * This gives stop testing a clear margin before natural completion.
219	       */
220	
221	      {
222	        unsigned char header[44];
223	        uint32_t length = 5 * (sizeof(vg_audio_tone) - sizeof(header));
224	        int ret;
225	        int fd;
226	
227	        memcpy(header, vg_audio_tone, sizeof(header));
228	        for (i = 0; i < 4; i++)
229	          {
230	            header[4 + i] = (length + 36) >> (i * 8);
231	            header[40 + i] = length >> (i * 8);
232	          }
233	
234	        fd = open("/mnt/emmc/bvo04/tone-stop.wav",
235	                  O_WRONLY | O_CREAT | O_TRUNC, 0644);
236	        if (fd < 0)
237	          {
238	            return EXIT_FAILURE;
239	          }
240	
241	        ret = vg_audio_writeall(fd, header, sizeof(header));
242	        for (i = 0; i < 5 && ret == OK; i++)
243	          {
244	            ret = vg_audio_writeall(fd, vg_audio_tone + sizeof(header),
245	                                   sizeof(vg_audio_tone) - sizeof(header));
246	          }
247	
248	        if (ret == OK && fsync(fd) < 0)
249	          {
250	            ret = -EIO;
251	          }
252	
253	        if (close(fd) < 0)
254	          {
255	            ret = -EIO;
256	          }
257	
258	        if (ret < 0)
259	          {
260	            return EXIT_FAILURE;
261	          }
262	
263	        printf("vgaudio: fixture /mnt/emmc/bvo04/tone-stop.wav bytes=%lu\n",
264	               (unsigned long)(length + sizeof(header)));
265	      }
266	
267	      return EXIT_SUCCESS;
268	    }
269	  else if (strcmp(argv[1], "codec") == 0)
270	    {
271	      static const uint16_t regs[] =
272	      {
273	        0x0000, 0x0001, 0x0003, 0x0005, 0x001c, 0x001d,
274	        0x002d, 0x002e, 0x004c, 0x0060, 0x0200, 0x0208,
275	        0x0210, 0x0300, 0x0420, 0x0601, 0x0602, 0x0610, 0x0611
276	      };
277	      size_t i;
278	      for (i = 0; i < sizeof(regs) / sizeof(regs[0]); i++)
279	        {
280	          uint16_t value;
281	          int ret = stm32_audio_codec_readreg(regs[i], &value);
282	          if (ret < 0)
283	            {
284	              printf("vgaudio: codec read 0x%04x failed: %d\n", regs[i], ret);
285	              return EXIT_FAILURE;
286	            }
287	
288	          printf("vgaudio: codec[0x%04x]=0x%04x\n", regs[i], value);
289	        }
290	
291	      return EXIT_SUCCESS;
292	    }
293	  else if (strcmp(argv[1], "txcheck") == 0)
294	    {
295	      int r[5] = {0};
296	      int ret = stm32_audio_tx_check(r, 5);
297	      printf("vgaudio: txcheck invalid-init=%d zero=%d odd=%d overcapacity=%d "
298	             "offset=%d rounds=20 result=%d\n", r[0], r[1], r[2], r[3],
299	             r[4], ret);
300	      return ret < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
301	    }
302	  else if (strcmp(argv[1], "id") == 0)
303	    {
304	      return vg_audio_id() < 0 ? EXIT_FAILURE : EXIT_SUCCESS;
305	    }
306	  else if (strcmp(argv[1], "sai") == 0)
307	    {
308	      vg_audio_sai();
309	      return EXIT_SUCCESS;
310	    }
311	  else if (strcmp(argv[1], "reg") == 0)
312	    {
313	      uint16_t val = 0;
314	      int off;
315	      int ret;
316	
317	      if (argc < 3)
318	        {
319	          vg_audio_usage();
320	          return EXIT_FAILURE;
321	        }
322	
323	      /* The codec has a 16-bit register map; the higher-numbered registers
324	       * (0x200 and up) hold the clocking and AIF configuration, so the range
325	       * has to cover them.
326	       */
327	
328	      off = (int)strtol(argv[2], NULL, 0);
329	      if (off < 0 || off > 0xffff)
330	        {
331	          printf("vgaudio: register offset out of range\n");
332	          return EXIT_FAILURE;
333	        }
334	
335	      ret = stm32_audio_codec_readreg((uint16_t)off, &val);
336	      if (ret < 0)
337	        {
338	          printf("vgaudio: reg 0x%02x read failed: %d\n", off, ret);
339	          return EXIT_FAILURE;
340	        }
341	
342	      printf("vgaudio: R%d (0x%02x) = 0x%04x\n", off, off, val);
343	      return EXIT_SUCCESS;
344	    }
345	
346	  vg_audio_usage();
347	  return EXIT_FAILURE;
348	}
