55	static int vg_audio_writeall(int fd, const unsigned char *data, size_t size)
56	{
57	  while (size > 0)
58	    {
59	      ssize_t n = write(fd, data, size);
60	      if (n < 0 && errno == EINTR)
61	        {
62	          continue;
63	        }
64	
65	      if (n <= 0)
66	        {
67	          return -EIO;
68	        }
69	
70	      data += n;
71	      size -= n;
72	    }
73	
74	  return OK;
75	}
